package io.scenariomesh.config; import java.nio.file.*;import java.time.*;import java.util.*;
public record ScenarioMeshConfig(boolean enabled,int workerCount,WorkerMode workerMode,Duration idleTimeout,int maxScenariosPerWorker,boolean restartOnBuildChange,Duration heartbeatInterval,Duration unhealthyAfter,String schedulingStrategy,Path reportingDirectory,boolean autoStartDaemon,List<String> jvmArgs){
 public enum WorkerMode{PERSISTENT,EPHEMERAL} public ScenarioMeshConfig{if(workerCount<1)throw new IllegalArgumentException("Invalid configuration: workers.count must be greater than 0");if(maxScenariosPerWorker<1)throw new IllegalArgumentException("Invalid configuration: workers.lifecycle.maxScenariosPerWorker must be greater than 0");jvmArgs=List.copyOf(jvmArgs);}
 public static ScenarioMeshConfig defaults(){return new ScenarioMeshConfig(true,Math.max(1,Runtime.getRuntime().availableProcessors()/2),WorkerMode.PERSISTENT,Duration.ofMinutes(10),50,true,Duration.ofSeconds(5),Duration.ofSeconds(20),"duration-aware",Path.of("target","scenariomesh"),true,List.of());}}
